// Find the App component source
const root = document.querySelector('#root');
const key = Object.keys(root).find(k => k.startsWith('__reactFiber$'));
let fiber = root[key];

// Find App component
function findComponent(fiber, name) {
  if (!fiber) return null;
  if (fiber.type && typeof fiber.type === 'function' && fiber.type.name === name) return fiber;
  let result = findComponent(fiber.child, name);
  if (result) return result;
  return findComponent(fiber.sibling, name);
}

const app = findComponent(fiber, 'App');
if (app) {
  return `App source: ${app.type.toString().substring(0, 1500)}`;
}
return 'App not found';

// Navigate the fiber tree more carefully
const root = document.querySelector('#root');
const key = Object.keys(root).find(k => k.startsWith('__reactFiber$'));
let fiber = root[key];

// Collect all component names
function walkTree(fiber, depth, results) {
  if (!fiber || depth > 15) return;
  if (fiber.type && typeof fiber.type === 'function') {
    const name = fiber.type.name || 'Anonymous';
    results.push({ name, depth, hasState: !!fiber.memoizedState });
  }
  if (fiber.type && typeof fiber.type === 'string') {
    // skip DOM nodes
  }
  walkTree(fiber.child, depth + 1, results);
  walkTree(fiber.sibling, depth, results);
}

const results = [];
walkTree(fiber, 0, results);
// Get unique component names with their depth
const unique = results.filter((r, i) => results.findIndex(x => x.name === r.name) === i);
return JSON.stringify(unique.slice(0, 30));
